insert into public.exam_questions (subject, question, options, answer) values ('상식', '사이버 공간에서 발생하는 명예훼손, 성희롱, 따돌림 등 언어적 폭력을 의미하는 용어는 무엇입니까?', '["사이버 폭력", "스토킹", "해킹", "피싱"]'::jsonb, 0);
