insert into public.exam_questions (subject, question, options, answer) values ('상식', '문학 작품 속에서 작가가 말하고자 하는 주된 생각이나 교훈을 무엇이라고 합니까?', '["플롯", "등장인물", "배경", "주제"]'::jsonb, 3);
